const SHOTS=[{key:'front',label:'대표 컷'}];

function slot(label){
  return `<svg viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${label} 사진 자리">
    <rect width="400" height="300" fill="#F0F3F1"/>
    <g stroke="#C9D2CD" stroke-width="2" opacity=".7"><path d="M150 150h100M200 100v100"/></g></svg>`;
}
const cardShot=it=>it.thumb?`<img src="${it.thumb}" alt="${it.name} 제품 사진" loading="lazy">`:slot(it.name);
const galShot=(it,s)=>{const u=it.photos&&it.photos[s.key];
  return u?`<img src="${u}" alt="${it.name} 사진" loading="lazy">`:slot(it.name);};

const cardHTML=it=>`
 <button class="card" type="button" data-id="${it.id}" aria-label="${it.name} 사양 보기">
   <div class="shot">${cardShot(it)}</div>
   <div class="body">
     <h3>${it.name}</h3>
     <p>${it.desc}</p>
     <div class="meta"><span>${CATNAME[it.cat]}</span><em>자세히 →</em></div>
   </div>
 </button>`;
